-- ============================================================
-- Improved Hunter's Mark: proc configuration
-- ============================================================
--
-- ProcFlags 332116 -- every way a hunter deals damage:
--
--   0x00000004 DONE_MELEE_AUTO_ATTACK
--   0x00000010 DONE_SPELL_MELEE_DMG_CLASS
--   0x00000040 DONE_RANGED_AUTO_ATTACK        (Auto Shot)
--   0x00000100 DONE_SPELL_RANGED_DMG_CLASS    (the shots)
--   0x00001000 DONE_SPELL_NONE_DMG_CLASS_NEG
--   0x00010000 DONE_SPELL_MAGIC_DMG_CLASS_NEG (Explosive Trap and friends)
--   0x00040000 DONE_PERIODIC                  (Serpent Sting, Lacerating Shot)
--
-- SpellFamilyName 0 and no masks, deliberately: this is "damage you deal",
-- not "damage from these spells", and a white swing carries no family at all.
--
-- DONE_PERIODIC is documented as "damage / healing", so this also fires on Mend
-- Pet ticks.  The script early-returns because GetDamageInfo() is null on a heal
-- proc, and the Hunter's Mark check would reject the pet as a target anyway.
--
-- A negative row covers all three ranks: unlike the 50/100% talents, the rank
-- scaling here lives in the aura's base points, not in the proc chance.
--
-- No Cooldown.  Unlike Taste for Blood, this cannot run away: the payout is a
-- fixed share of damage actually dealt, so it is self-limiting by construction
-- rather than by throttle.  Throttling it would instead make the healing depend
-- on how many small hits you land, which is worse.

DELETE FROM `spell_proc` WHERE `SpellId` IN (-19421, 19421, 19422, 19423);
